(() => {
  const course = window.textbookCourses?.baranov7part2;
  if (!course) return;

  const solutions = {
  "308": "Стиль речи: учебно-научный. Тип речи: рассуждение с элементами повествования.\nПредложение с определением: Отзыв — это оценочное устное или письменное высказывание.",
  "309": "Правила доброжелательного отзыва:\n1. Высказывать мнение тактично и вежливо.\n2. Приводить аргументы и доводы (анализ текста, цитаты, статистика).\n3. Отмечать положительные стороны работы.\n4. На недостатки указывать в мягкой форме, чтобы не обидеть автора и помочь ему.\nКлючевые слова: мнение, отзыв, оценка, аргументы, цитирование, достоинства, недостатки, тактичная форма.",
  "310": "1-й отзыв: просто констатация факта без аргументов.\n2-й отзыв: содержит небольшую аргументацию («необыкновенно забавный и замечательный попугай»), но она субъективна.\n3-й отзыв: наиболее убедительный. В нем есть аргументы («умная кошка», «кормит чужих котят», «не раз улыбнулись»), обоснован вывод.",
  "311": "В изложении используются просторечные слова и разговорные конструкции: «она пришла за помощью», «спонсора».\nТактичный отзыв: \"В твоем изложении хорошо передана суть басни. Однако стоит обратить внимание на стиль речи. Использование слова «спонсор» неуместно в тексте о классической басне. Также фразу «она расстроилась» лучше заменить на более подходящую по стилю.\"",
  "312": "Сочинение ученика соответствует теме, но доводы недостаточно убедительны.\nОтзыв: \"В сочинении четко выражена твоя позиция. Ты привел интересный аргумент о том, что пение — это тоже труд. Однако стоит расширить доказательную базу. Хотелось бы, чтобы автор дополнил текст рассуждением о том, почему важно думать о будущем, как это делал Муравей.\"",
  "313": "Недочеты: много повторов (выточить - вытачивании - выточил; кегли - кеглей; шара - шаров). Предложения можно сделать более связными.\nОтзыв: \"Сочинение соответствует теме и подробно описывает процесс работы. Автор показал, как упорство помогло достичь результата. Однако в тексте имеются некоторые речевые недочёты: часто повторяются однокоренные слова. Рекомендуется использовать синонимы.\"",
  "314": "Пример отзыва (самостоятельно):\n\"Недавно я посмотрел фильм «Чебурашка». Мне очень понравилась эта картина. Режиссеру удалось создать трогательную историю о дружбе и семейных ценностях. Актерская игра на высоте. Единственный недостаток, на мой взгляд, — немного затянутое начало. В целом, рекомендую фильм к просмотру!\"",
  "315": "Творческое задание для работы в паре. (Выполняется индивидуально в классе).",
  "316": "Заголовок: Что такое учебный доклад.\nСложный план:\nI. Понятие доклада и его формы.\n1. Определение доклада как научно-исследовательской работы.\n2. Публичное сообщение.\nII. Структура доклада.\n1. Вступление (привлечение внимания).\n2. Основная часть (важные сведения).\n3. Заключение (выводы).\nIII. Как сделать доклад интересным.\n1. Неизвестные факты и примеры.\n2. Спорные вопросы.\n3. Наглядность (рисунки, презентации).\nIV. Подготовка к выступлению.",
  "317": "Творческое задание. Текст для доклада: \"Взаимопроникновение стилей языка\". (Выполняется самостоятельно).",
  "318": "Поисковые запросы (например, танец \"Калинка\"):\n1. русский народный танец калинка история\n2. калинка танец движения описание\n3. кто придумал танец калинка\n4. музыка для танца калинка\n5. костюмы для русского народного танца калинка\n6. калинка малинка значение слова\n7. калинка танец видео смотреть\n8. популярность танца калинка в мире",
  "319": "Ученик 2 получит более разнообразную и интересную информацию, так как его запросы конкретные, охватывают разные аспекты (виды, рекорды, физика полета, литература, музеи). Запросы первого ученика слишком общие и примитивные.",
  "320": "Вступление: первый абзац (привлекает внимание фактом о 40% несловесной информации).\nНовые сведения: виды невербальных средств общения (мимика, взгляд, интонация, жесты, поза).\nВывод автора в заключении: неуместные невербальные средства мешают общению, выдают неуверенность. Специалисты советуют следить за ними и репетировать выступления.",
  "321": "В отзыве указаны достоинства (автор дает определение, показывает значение) и недостатки (тема слишком широкая, нет примеров, наглядности). Доводы убедительные. Отзыв можно назвать тактичным и вежливым.",
  "322": "Вступление: первый абзац (\"Существует несколько изобретений...\").\nОсновная часть: абзацы со 2 по 6 (про телеграф, телефон, радио, электронную почту).\nЗаключение: последний абзац (\"В настоящее время...\").\nЧто добавить: можно добавить информацию о мобильной связи, смартфонах, мессенджерах и видеозвонках, чтобы доклад отражал современность.",
  "323": "Творческое задание (исследовательский доклад). Выполняется самостоятельно.",
  "324": "Творческое задание (доклад о празднике). Выполняется самостоятельно.",
  "325": "Памятка «Как подготовить доклад»:\n1. Выберите интересную тему.\n2. Соберите информацию из разных источников (книги, интернет).\n3. Составьте план (вступление, основная часть, заключение).\n4. Напишите текст, используя понятный язык.\n5. Подготовьте наглядные материалы (презентацию, картинки).\n6. Отрепетируйте выступление дома.",
  "326": "1. Уже совсем стемнело и начинало холодать; в роще звучно щёлкал соловей.\n(стемнело, начинало холодать - состояние природы).\n2. На дворе чуть брезжило. (брезжило - состояние природы).\n3. Ещё нигде не румянилась заря, но уже забелелось на востоке. (забелелось - состояние природы).\n4. Навстречу тянуло сладким ветром летней ночи и моря. (тянуло - состояние природы).\n5. Кажется, погода портится. Как бы не затянуло всё облаками. (затянуло - состояние природы).\n6. Лодырю всегда нездоровится. (нездоровится - состояние человека).\n7. От усталости стучало в висках. (стучало - состояние человека).\n8. Так бы и побежала. Без цели, без оглядки, только чтоб дышалось сильнее, чтоб грудь саднило. (дышалось, саднило - состояние человека).\n9. Мне часто вспоминается теперь и эта река... (вспоминается - состояние человека).\n10. К ночи в погоду становится очень холодно и росисто. (становится холодно и росисто - состояние природы).\n11. Знала, что он в меня влюблён был, и от этого мне тоже гордо было. (гордо было - душевное состояние человека).\n(Подчеркнуть глаголы как сказуемые в безличных предложениях).",
  "327": "Предложения со словами категории состояния природы и окружающей среды:\n1. В комнате было тихо... (тихо)\n3. К ночи в погоду становится очень холодно и росисто. (холодно, росисто)\n4. Было ещё жарко, от туч сумрачно. (жарко, сумрачно)\n\nПредложения со словами категории душевного состояния человека:\n2. ...и на душе становится так тепло и отрадно... (тепло, отрадно)\n5. ...в доме было страшно. (страшно)\n6. Хорошо и беззаботно мне на траве... (хорошо, беззаботно)\n7. ...как на душе светло и тихо. (светло, тихо)\n(Глаголы-связки \"было\", \"становится\" вносят значения времени и наклонения).",
  "328": "состояние природы — ветрено, жарко, солнечно, морозно, прохладно;\nсостояние среды — грязно, сыро, темно, светло, пыльно, душно;\nфизическое состояние живых существ — больно, дурно, приятно, тяжело, зябко;\nэмоциональное состояние человека — весело, грустно, страшно, радостно, обидно;\nинтеллектуальное состояние человека — интересно, ясно, понятно, любопытно;\nоценку какого-либо состояния, положения — легко, рано, хорошо, поздно;\nмодальную оценку состояния — нужно, можно, нельзя, необходимо, надо.",
  "329": "1. холоднее (нач.ф. холодно)\n2. Веселее (нач.ф. весело)\n3. больнее (нач.ф. больно)\n4. теплее (нач.ф. тепло)\n5. грязнее (нач.ф. грязно)",
  "330": "1. светлее, радостнее (прилагательные, относятся к подлежащему \"глаза\").\n2. быстрее (наречие, относится к глаголу \"идите\").\n3. легче (категория состояния, сказуемое в безличном предложении).\n4. страшнее (категория состояния, сказуемое в безличном предложении).\n5. яснее (наречие, относится к глаголу \"слышались\").\n6. Справедливее (категория состояния).\n7. мощнее (прилагательное, сказуемое).\n8. ловче и отчаяннее (прилагательные, относятся к \"парня\").",
  "331": "1. Сегодня так светло кругом...\n2. И скучно, и грустно, и некому руку подать в минуту душевной невзгоды... (запятые при однородных, союз И).\n3. Я вступил в эту жизнь, пережив её уже мысленно, и мне стало скучно и гадко. (деепричастный оборот; запятая перед союзом И в сложном предложении).\n4. Смотрите, ведь уже поздно, холодно. (вводное слово; однородные члены).\n5. Шалун уж заморозил пальчик: ему и больно, и смешно, а мать грозит ему в окно. (двоеточие БСП; запятая при И...И; перед А).\n6. Пушкин любил эту землю. Он ходил по лесу без сюртука, в рубашке, часто на босу ногу, в ветер, и дождь, и прохладу, а не только когда было тихо и жарко. (однородные члены; перед А; перед КОГДА).\n7. Писать тебе посланье мне было недосуг.\n8. Над старостью смеяться грех.\n11. Но теперь ей ничего не надо, отзвенел давно звеневший сад. (БСП).\nГруппы: светло, поздно, холодно, тихо, жарко (состояние природы/среды). Скучно, грустно, гадко, больно, смешно (состояние человека). Недосуг, грех, надо (модальная/моральная оценка).",
  "332": "Состояние природы/человека: тепло, ярко, хорошо, весело.\nЧасть речи: категория состояния (хорошо, весело, грустно), наречие (ярко), прилагательное (тёплым).\nЗнаки препинания:\nБывают дни: повеет тёплым ветром,\nПроглянет солнце, ярко озаряя\nИ лес, и степь, и старую усадьбу,\nПригреет листья влажные в лесу,\nГлядишь — и всё опять повеселело!\nКак хорошо, кочующие птицы,\nТогда у нас! Как весело и грустно\nВ пустом лесу меж чёрными ветвями,\nМеж золотыми листьями берёз\nСинеет наше ласковое небо!",
  "333": "Тип речи: повествование с элементами описания.\nСловосочетания с наречиями: жестоко страдал; надетые специально.\nСловосочетания со словами категории состояния: было стыдно; стало весело; славно и легко (на душе).",
  "334": "1. В Мещёрском крае можно увидеть сосновые боры, где так торжественно и тихо, что бубенчик заблудшей коровы слышен далеко, почти за километр.\n2. В Мещёрском крае можно увидеть лесные озёра с тёмной водой, обширные болота, покрытые ольхой и осиной, одинокие избы лесников, пески, можжевельник, вереск, косяки журавлей и знакомые нам под всеми широтами звёзды.\n3. Достаточно сказать, что этот край лежит между Владимиром и Рязанью, недалеко от Москвы, и является одним из немногих уцелевших лесных островов, остатком «великого пояса хвойных лесов».\nСлова категории состояния: торжественно, тихо (состояние природы); можно (модальная оценка); достаточно (мера).",
  "335": "1. тревожно и боязно — категория состояния. Обозначает душевное состояние человека. Неизменяемое. В предложении — сказуемое.\n2. безмолвно и тихо — категория состояния. Состояние среды. Неизменяемое. Сказуемое.\n3. просторно — категория состояния. Состояние среды. Неизменяемое. Сказуемое.\n4. жарко и душно — категория состояния. Состояние среды. Неизменяемое. Сказуемое.\n5. ясно — категория состояния. Оценка состояния. Неизменяемое. Сказуемое.\n6. нельзя — категория состояния. Модальная оценка. Неизменяемое. Сказуемое.",
  "336": "Текст называется «Обыкновенная земля», потому что автор показывает красоту в простых, неприметных вещах.\nСжатое изложение:\nВ Мещёрском крае нет особенных красот и богатств. Однако этот край обладает большой притягательной силой. Он скромен, в нём заключена вся прелесть русской природы. В Мещёрском крае можно увидеть цветущие луга, сосновые боры и лесные озёра. В первые дни этот край кажется обыкновенным, но потом он делается всё богаче и милее сердцу, когда о ней можно рассказывать удивительные истории.",
  "337": "(Выполняется самостоятельно с использованием словаря иностранных языков).",
  "338": "Основная мысль: А.Х. Востоков стоял у истоков сравнительно-исторического изучения славянских языков и придал отечественному языкознанию научную строгость.\nКраткий пересказ: В начале XIX века в Европе языкознание стало наукой. Благодаря сравнительно-историческому методу появилась научная строгость. В России основоположником изучения славянских языков этим методом был Александр Христофорович Востоков.",
  "339": "Арина Родионовна нянчила Пушкина. Она рассказывала ему русские сказки. Она была верной «подругой дней суровых» опального поэта.\nИз слов правого столбика составить предложения не удалось, потому что это служебные части речи.",
  "340": "Словосочетания без предлога: вспоминать полёт, наблюдать восход солнца, произвести посадку, окончить полёт, поставить трап.\nСловосочетания с предлогом: вспоминать о полёте, говорить с ним, наблюдать за облаками, смотреть в иллюминатор, любоваться пейзажем, подниматься по трапу.",
  "341": "Ездить на машине (на чём?), ездить в автобусе (в чём?), ездить с комфортом (с чем?).",
  "342": "1) с временным значением: остаться после старта, закончить перед отплытием.\n2) с пространственным значением: доехать до границы, находиться в двух часах лёту, выбираться из трюма, остаться в каюте, возникнуть за кормой, вынырнуть из-под скалы.\n3) с причинным значением: остановиться из-за неисправности мотора, задержать из-за непогоды, оказаться вследствие нездоровья, выросли благодаря дождям.",
  "343": "Основная мысль: История Москвы.\nСтиль: Научно-популярный.\nПлан:\n1. Первое поселение.\n2. Упоминание.\n3. Столица.",
  "344": "Значение орфографии огромно.",
  "345": "Работать на фабрике (П.п.), на заводе (П.п.), в больнице (П.п.), в библиотеке (П.п.), в магазине (П.п.), на бирже (П.п.), в цехе (П.п.). Учиться в школе (П.п.), в техникуме (П.п.), на курсах (П.п.), в лицее (П.п.), в институте (П.п.), на историческом факультете (П.п.). Жить в Сибири (П.п.), в Заполярье (П.п.), на Урале (П.п.), на Алтае (П.п.), в Москве (П.п.).",
  "346": "Поступить по окончании школы, встретиться по прибытии, обсудить по возвращении, вход по предъявлении, сообщить по окончании, поговорить по приезде.",
  "347": "Ошибиться по невнимательности (Д.п.), по рассеянности (Д.п.), по небрежности (Д.п.). Отсутствовать по болезни (Д.п.), по уважительной причине (Д.п.).",
  "348": "Обращать внимание на мелочи, уделять внимание книге, отзыв о книге, рецензия на работу, отчитываться в работе, сделать отчет о новой технике.",
  "349": "Рассказал о недостатках, указал на недостатки, упомянул о недостатках.",
  "350": "1. Оплатить билет. 2. Уверенность в победе. 3. Изобразить Бородинское сражение. 4. Делиться своими достижениями. 5. Доказывать свою правоту. 6. Указать на недостатки. 7. Отчитаться в работе. 8. Разъяснять правила. 9. Таблетки от головной боли.",
  "351": "Речь в защиту предлогов \"из\", \"с\". Правильно говорить: прийти из школы, из магазина.",
  "352": "Переходят через улицу, строят позади дома, пишут на конверте, накинут поверх пальто, отступят от темы, разделят на пять, разыщут благодаря находчивости, вдумаются в смысл, прибавят к двум, заменят ввиду ветхости, бегают около дома, выпишут из книги, движутся вдоль дороги, шагают в колонне, поступят наперекор обычаю, сбегают с горы, готовят в течение месяца, встанут с постели, делятся с друзьями, ждут с час, находятся напротив дома, уложат поперёк дороги, выстроены вблизи стадиона, возвышаются посреди площади, организуют в целях борьбы со стихией.",
  "353": "1. Вокруг (предлог). 2. Вокруг (наречие). 3. Мимо (предлог). 4. Около (предлог). 5. Мимо (наречие). 6. Около (предлог).",
  "354": "1. Благодаря обилию. 2. Согласно предсказанию. 3. Согласно графику. 4. Навстречу трактористу. 5. В течение более раннего срока.",
  "355": "1. Из-за дождя интересная экскурсия не состоялась. 2. Поход в горы был отложен из-за сильного тумана. 3. Из-за разнообразной программы гастроли прошли успешно. 4. Благодаря мастерству...",
  "356": "Лосьон для защиты от укусов комаров.\nСостав для выведения пятен.\nЖидкость для растяжки обуви.\nТаблетки от кашля.\nКрем для чистки обуви.",
  "357": "1. из наших областей (не тот предлог). 2. выясним, куда (лишний предлог). 3. озабочены тем (лишний предлог). 4. нашли общий язык с семьей (не тот предлог). 5. около четырехсот (не тот падеж). 6. неписаным законам (не тот падеж). 7. на эту проблему (не тот предлог).",
  "358": "На нас / за нами.\nИз-за замены предлога меняется смысл: либо мы преследуем, либо преследуют нас.",
  "359": "Различаются. \"Глядеть в небо\" - смотреть на физическое пространство. \"Глядеть на небо\" - смотреть на видимый свод.",
  "360": "С простыми предлогами: останется позади дома (позади), крепнет по мере роста (по мере), мчится вдоль по шоссе (вдоль по - сост), собираемся по случаю праздника (по случаю).\nС составными: сделан наподобие корзинки, ошибся вследствие невнимательности, собрался по поводу постановления, утеплить ввиду холодов.",
  "361": "Определить форму глаголов... (безличные, определенно-личные и т.д.).",
  "362": "Разбор предлогов: над (простой, непроизводный), с (простой, непроизводный).",
  "363": "Детей поразила реальность картины художника.",
  "364": "Репортаж о гимнастках. В спортивном зале шумно...",
  "365": "Монолог комментатора баскетбольного или футбольного матча.",
  "366": "Слитно: впереди, внутри, вблизи, вокруг, навстречу, позади.\nРаздельно: по случаю.",
  "367": "В течение, в продолжение, насчёт, ввиду, вследствие.",
  "368": "Впоследствии какой-то задержки...",
  "369": "Ранняя и суровая весна. Описание бури.",
  "370": "Сочинение \"Как наступает весна в нашем городе\".",
  "371": "Заголовок: Роль союзов в языке.\nОсновная мысль: Союзы созданы человеком для выражения логической связи между высказываниями.\nСтиль: научно-учебный.\nСоюзы, соединяющие однородные члены: и, или.\nСоюзы, соединяющие простые предложения: что бы, если, что, когда, так как.\nСинонимы: оттого что - так как, вследствие того что - так как, в силу того что - так как, благодаря тому что - так как.\nТекст: (переписан с вставкой букв: реальном, ничего, созданы, выражения, убедиться, непосредственном наблюдении, различных, реальных, ситуаций, видите, сломалось, не нуждаетесь, каких-либо связующих, причина, сообщается, письменной, бумагах, выразить).",
  "372": "Однородные члены: Живи, не холодей, делай.\nСоюзы: и, чтоб, и.\nМетафора \"время память запрядёт\" означает, что время сохранит память о хорошем человеке.",
  "373": "Тип речи: повествование.\nОсновная мысль: Красота падающего снега.\nСиноним к слову воротиться: вернуться.\nСложные предложения:\n1. Чтобы вполне насладиться этой картиной, я вышел в поле, и чудное зрелище представилось глазам моим.\n2. Всё безграничное пространство вокруг меня представляло вид снежного потока, будто небеса разверзлись, рассыпались снежным движением и поразительной тишиной.\n3. Наступали длинные зимние сумерки; падающий снег начинал закрывать все предметы, и белым мраком одевал землю.\n4. Я воротился домой, но не в душную комнату, а в сад и с наслаждением ходил по дорожкам, осыпанным снежными хлопьями.\n5. Засветились огоньки в крестьянских избах, и бледные лучи легли поперёк улицы.\n6. Я вошёл в дом, но и там стоял у окошка до тех пор, покуда уже нельзя было различить опускающихся снежинок.",
  "374": "Грамматические основы подчеркнуты (вид печален, воздух дышит, стебль колышет, ветви шевелит, природа не проснулась, она послышала и улыбнулась).\nПротивопоставление выражают союзы: А, Но.\nГлаголы в переносном значении: дышит, колышет, шевелит, проснулась, послышала, улыбнулась.\nОрфограммы: печален, дышит, колышет, шевелит, природа, редеющего.",
  "375": "Тип речи: рассуждение. Стиль: публицистический.\nОтношения между простыми предложениями в сложном выражены с помощью союзов: потому что (причина), чтобы (цель), то есть (пояснение).\nОбобщающее слово при однородных членах: плоды.\nТекст списывается, вставляются буквы и запятые.",
  "376": "1. пока (п.с.)\n2. оттого что (с.с.)\n3. потому что (с.с.)\n4. что (п.с.), потому что (с.с.)\n5. Только что (с.с.)\n6. потому что (с.с.)",
  "377": "1. Мы вернулись, потому что стемнело.\n2. Цветы завяли оттого, что их не поливали.\n3. После того как начался дождь, все разбежались.\n4. С тех пор как мы встретились, прошло два года.\n5. Я пришел затем, чтобы помочь.\n6. По мере того как мы продвигались, лес редел.\n7. Он устал, потому что долго работал.\n8. Она улыбнулась оттого, что вспомнила шутку.\n9. После того как фильм закончился, мы пошли спать.\n10. С тех пор как я переехал, мы не виделись.",
  "378": "Текст о Ф.И. Буслаеве. Основная мысль: важность изучения родного языка.\nВысказывание означает: развитие языка идет параллельно с духовным развитием.",
  "379": "Сочинение на лингвистическую тему.\nПунктуация способствует ясности в изложении мыслей. Отделяя одно предложение от другого, знаки препинания помогают правильно понять смысл.",
  "380": "Сложноподчиненные (п.): 1, 2, 4.\nСложносочиненные (с.): 3, 5.",
  "381": "1. Ребята очень устали, и мы сделали привал. (и)\n2. Путешественники приблизились к роднику, чтобы набрать воды. (чтобы)\n3. Туристы разбили лагерь, когда стемнело. (когда)\n4. Поезд замедлил ход, но не остановился. (но)\n5. Мы выгрузили багаж, когда приехали. (когда)\n6. Город еще только просыпается, и на улицах пусто. (и)\n7. В окнах высотных зданий отражается солнце, когда наступает утро. (когда)",
  "382": "1. В парке в полной темноте сиренево светился снег, и на нём чернели оттаявшие и скованные морозом тропы.\n2. Месяц светил с высокого неба, и в степи видна была каждая травинка.\n3. Мать погладила рукой холодную кожу чемодана, облокотилась на него и, довольная, начала рассматривать публику.\n4. Во всякой комнате, даже очень уютной и до смешного маленькой, есть нежилой угол.\n5. Дверь хлопала и открывалась снова. Входили люди и врывался пар.",
  "383": "1. Пока я производил наблюдения, мои спутники протоптали дорогу на перевал. (Пока)\n2. По мере того как угасал день, в лесу наступала тишина. (По мере того как)\n3. Котлованы очень опасны для заселения, потому что во время дождей они затопляются водой. (потому что)\n4. Несмотря на то что небо было покрыто кучевыми облаками, солнце светило ярко. (Несмотря на то что)\n5. Солнце имело вид оранжевого диска с резко очерченными краями, так что мы могли смотреть на него невооружённым глазом. (так что)",
  "384": "1. Великий человек лишь громок на делах, и думает свою он крепко думу без шуму.\n2. Я правил к берегу разлива, и хата, крытая соломою, с крыльцом, ко мне навстречу шла, мигая мне пугливо уединённым огоньком.\n3. Мне приходилось ночевать в стогах и в октябре, когда трава на рассвете покрывается инеем, как солью.\n4. А взводы шагали, шагали, и пели, и сон отлетел, и пропала усталость.\n5. Пока мать накрывала на стол, отец сходил вместе с нами к морю.",
  "385": "Составление предложений по схемам.\n1. [ ], и [ ]. Пошел дождь, и мы спрятались.\n2. [ ], (если...). Мы пойдем гулять, если не будет дождя.\n3. [ ], но [ ]. Солнце светило, но было холодно.\n4. [ ], (потому что...). Я не пришел, потому что заболел.\n5. [ ], а [ ]. Один брат читал, а другой играл.",
  "386": "1. Звёзды меркнут и гаснут. (соединительный, с.) Сердце счастья и радостей просит, а годов невозвратный полёт и последнюю радость уносит. (противительный, п.) Птички солнышка ждут, птички песни поют, и стоит себе лес, улыбается. (соединительный, с.)\n2. Ночь холодная мутно глядит под рогожу кибитки моей, под полозьями поле скрипит, под дугой колокольчик гремит, а ямщик погоняет коней. (противительный, п.) И расхлестнулась вдаль дорогой шуршащая лесами тьма. (соединительный, с.) Я на руках не то у ели, не то у матери родной. (разделительный, р.) Лес ли со стоном сосны клонит, или вьюга свой мне стон несёт? (разделительный, р.)",
  "387": "Пословицы списываются, вставляются буквы, расставляются запятые по схемам:\n1. Не от росы урожай, а от поту.\n2. Неправдой свет пройдёшь, да назад не воротишься.\n3. Добрая пословица не в бровь, а в глаз.\n4. Красна ягода, да на вкус горька.\n5. Мал ёрш, да колюч.\n6. Без нитки да иголки шубы не пошить.\n7. Мал золотник, да дорог.\n8. Ищи товарища лучше себя, а не хуже себя.",
  "388": "Списывание монолога Пимена (Не то дождь со снегом, не то снег с дождём).\nЗапятая ставится перед второй частью составного союза.",
  "389": "1. В русский язык слово «автомобиль» пришло из французского. Во французском как первая часть этого слова, так и вторая — заимствованы из других языков. Из греческого взято «аутос» (авто), что означает «сам», а из латинского «мобилис», то есть «подвижный».\n2. Людей перевозят не только огромные междугородные автобусы, но и легковые автомобили.\n3. Среди легковых машин есть как большие нарядные, так и маленькие скромные.\n4. Автомобиль вышел из соревнований. Не то тормоз сломался, не то мотор оказался неисправным.",
  "390": "1. [ ], и [ ]. Солнце село, и стемнело.\n2. [ ], или [ ]. Мы поедем на море, или мы останемся дома.\n3. То ___, то ___. То светило солнце, то шел дождь.\n4. Или ___, или ___. Или он придет, или я позвоню.",
  "391": "Фрагменты анализируются. Союз \"и\" присоединяет последующее предложение к предшествующему. Союз выполняет роль связки. Однородные сказуемые подчеркиваются.",
  "392": "Списывание, расстановка знаков завершения:\nРазмышляя о Пушкине, люди невольно сравнивают себя с ним. А сделал ли бы и я так? А поступил бы так же? А что я думаю об этом? Эти размышления способствуют пробуждению в наших душах и умах самых лучших, самых высоконравственных мыслей и устремлений. В конечном счёте это и есть самовоспитание добром и красотой человеческой души. (Д. Лихачёв)",
  "393": "Союз \"но\" обрывает одну тему и обозначает переход к новой в обоих отрывках.",
  "394": "(Сочинение \"Я сижу на берегу...\").\nЯ сижу на берегу моря. Пришел сюда отдохнуть и насладиться тишиной. Волны тихо шепчут, а чайки кричат вдали...",
  "395": "Лингвистическое исследование. Повторяющиеся союзы у А. Пушкина служат для усиления выразительности речи, создания ритма.",
  "396": "1. Ямщики подвязали колокольчики, чтобы звон не привлёк внимания сторожей. (целевой)\n2. По синим волнам океана, лишь звёзды блеснут в небесах, корабль одинокий несётся, несётся на всех парусах. (временной)\n3. Все возы, потому что на них лежали тюки с шерстью, казались очень высокими и пухлыми. (причинный)\n4. Чичиков не заметил, как въехал в середину обширного села с множеством изб и улиц. (изъяснительный)\n5. Оттого что облака почти касались верхушек берёз, на земле было тихо и тепло. (причинный)",
  "397": "1. Я в сотый раз пожалел, что не родился художником. (изъяснительный)\n2. Слова у Пришвина цветут, сверкают. Они то шелестят, как травы, то бормочут, как родники, то пересвистываются, как птицы, то позванивают, как первый лёд, то ложатся в нашей памяти медлительным строем. (сравнительный)\n3. Если обращаться к примерам из собственной жизни, то я впервые увидел всё разнообразие красок русского ненастья после картины Левитана «Над вечным покоем». (условный)\n4. Я плыл по реке и вдруг услышал, как в небе кто-то начал осторожно переливать воду из звонкого стеклянного сосуда в другой такой же сосуд. (изъяснительный)\n5. Было так тихо, будто город вымер. (сравнительный)\n6. Старик называл мне ветер и следил, чтобы я правильно записывал его названия. (изъяснительный)",
  "398": "1. Как только появился первый автомобиль, решили научить улицу разговаривать, дать ей точный и выразительный язык знаков.\n2. Едва на светофоре зажегся зелёный свет, дорогу можно переходить.\n3. Перед тем как под улицами Москвы протянулись подземные коридоры, движение стало более безопасным.\n4. После того как построили подземные переходы под Триумфальной площадью, здесь было тесно и пешеходам, и автомобилям.\n5. Прежде чем светофоры нового типа установят повсюду, машинам не придется простаивать у перекрестков.",
  "399": "1. [ ], (где...). Я люблю библиотеку, где много книг.\n2. [ ], (потому что...). Я читаю, потому что это интересно.\n3. [ ], (куда...). Мы пошли туда, куда нас позвали.\n4. [ ], (чтобы...). Я взял книгу, чтобы прочитать.",
  "400": "Морфологический разбор:\nкогда - союз, подчинительный, простой, неизменяемое слово, не член предложения.\nи - союз, сочинительный, соединительный, простой, неизменяемое слово, не член предложения.",
  "401": "Кем бы вы ни стали, мои юные друзья, куда бы ни позвали вас пути-дороги, пусть всегда рядом с вами будут любимые книги!\nОгромный, прекрасный мир жизни нашей страны и наших сверстников открывается в миллионах книг. Авторы детских книг — самые большие ваши друзья.\nХотелось бы, чтобы вы, ребята, крепко дружили с произведениями наших классиков: Пушкина, Лермонтова, Гоголя, Некрасова, Льва Толстого, Горького. Прочитав книги этих писателей, вы почувствуете себя сильнее, сумеете глубже оценить свои поступки и поступки окружающих, ощутите всю прелесть прекрасного русского языка.",
  "402": "Сочинение на тему «Книги». Книга — наш друг и советчик, так как из нее мы черпаем знания, она формирует наше мировоззрение.",
  "403": "На крутом берегу Волги в живописной местности Ивановской области есть город Плёс. Также названы посёлки в Пензенской и Саратовской областях. То же слово включено и в другие географические названия: Чёрный Плёс в Челябинской области, Плесо на Колпи в Вологодской области. Этот корень содержится также в названиях, распространённых в других местностях: Плесецк в Архангельской области, Плесо-Курья в Кулундинской степи.\nМногие географические названия возникли от названий водных объектов.",
  "404": "1. В начале 1806 года Николай Ростов вернулся в отпуск. Денисов ехал тоже домой, в Воронеж, и Ростов уговорил его ехать с собой до Москвы и остановиться у них в доме.\n2. Ростов, не желая никому дать предупредить себя, скинул шубу и на цыпочках побежал в тёмную большую залу. Всё то же: те же ломберные столы, та же люстра в чехле.\n3. Все кричали, говорили и целовали его в одно и то же время.\n4. Соня тоже держалась за его руку и вся сияла.\n5. Голубчик, Денисов! — взвизгнула Наташа, не помнившая себя от восторга, подскочила к нему и обняла и поцеловала его. Все смутились поступком Наташи... Денисов тоже покраснел, но улыбнулся и взяв руку Наташи, поцеловал её.",
  "405": "1. Смотри, кума, чтобы не осрамиться: недаром говорится, что дело мастера боится.\n2. Возьми на час терпенья, чтобы квартет в порядок наш привесть.\n3. Берись за то, к чему ты сроден, коль хочешь, чтоб в делах успешный был конец.\n4. Не правда ли, что мы краса долины всей? Что нами дерево так пышно и кудряво, раскидисто и величаво? Что б было в нём без нас?",
  "406": "1. Сверху очень осторожно, чтобы не смешать жидкости, наливают слой чистой воды.\n2. К выводу о существовании сил всемирного тяготения пришёл Ньютон в результате изучения движения Луны вокруг Земли и планет вокруг Солнца.\n3. Обычно нужно приложить значительное усилие, чтобы тело, состоящее из твёрдого вещества, согнуть, сдавить или разорвать.\n4. Нужно небольшое усилие, чтобы отделить одну часть жидкости от другой.\n5. Чтобы определить плотность вещества, надо массу тела разделить на его объём.\nСтиль: научный.",
  "407": "1. Выдумывание названий — особый талант. Есть люди, которые хорошо пишут, но не умеют давать названия своим вещам. И наоборот. Так же как есть люди, которые превосходно рассказывают, но плохо пишут. Нужен сильный талант, такой, как у Горького, чтобы многократно рассказывать одну и ту же историю и потом написать её свежо и по-иному, чем сложился словесный рассказ!\n2. В посёлке этом сотни лет живут рыбаки. Поколения сменяют друг друга. Но так же, как и сотни лет назад, рыбаки уходят в море за салакой. И так же, как и сотни лет назад, не все возвращаются обратно. Но что бы ни случилось, всё равно надо и дальше делать своё дело — опасное и тяжёлое, завещанное дедами и отцами. Уступать морю нельзя.",
  "408": "(Устный ответ/рассуждение о труде рыбаков). Труд рыбаков связан с опасностью, но они продолжают этим заниматься, так как это их призвание и способ заработать на жизнь.",
  "409": "1. К берегу реки лыжники направились дальним путём, через лес, зато получили огромное удовольствие. Спрячься за то дерево, сказал мне брат.\n2. На лыжах по этому лесу они шли впервые. Наш класс упорно готовился к лыжным соревнованиям, поэтому мы и победили в кроссе.\n3. Ребята из нашей школы завоевали немало призов, потому что тренирует их талантливый мастер спорта. Первая группа лыжников пойдёт по тому берегу реки, а вторая — по этому, приказал тренер.",
  "410": "Человек приходит поселиться на новом месте, где до него ни одна нога не ступала. Он рубит дом, бросая на землю щепки. Он топит печь и, выгребая из неё золу, выбрасывает рядом с домом. Он ест мясо и швыряет себе под ноги кости. Он разбил горшок и черепки втоптал в грязь. Он потерял монету. У него прохудился сапог, и за порог полетела рваная подмётка. Потом у него сгорел дом. Человек разровнял пожарище, оставив в земле обгорелые брёвна нижних венцов, привёз песку, чтобы засыпать золу и головешки, и построил новый дом. В древности не вывозили на поля навоз, и он оставался лежать под пожарищами хлевов.\nТак из года в год медленно, но непрерывно происходит образование культурного слоя на месте человеческих поселений.\n\nПовторение сведений о предлогах и союзах",
  "411": "(Творческое задание на выбор о раскопках).",
  "412": "(Просмотр слов с непроверяемыми орфограммами, составление плана/сообщения).",
  "413": "(Просмотр слов с непроверяемыми орфограммами, составление плана/сообщения).",
  "414": "К вечеру, перед самыми сумерками, проходил я по Вознесенскому проспекту. Я люблю мартовское солнце в Петербурге, особенно закат, разумеется, в ясный морозный вечер. Вся улица вдруг блеснёт, облитая ярким светом. Все дома как будто вдруг засверкают. Серые, жёлтые и грязно-зелёные цвета их потеряют на миг всю свою угрюмость; как будто на душе прояснеет, как будто вздрогнешь, или кто-то подтолкнёт тебя локтем. Удивительно, что может сделать один луч солнца с душой человека!\nНо солнечный луч потух; мороз крепчал, и начал пощипывать за нос; сумерки густели. (Ф. Достоевский)",
  "415": "Сравнение картин и стихов. Выписывание орфограмм из тем \"Предлог\" и \"Союз\".",
  "416": "Сравнение картин и стихов. Выписывание орфограмм из тем \"Предлог\" и \"Союз\".",
  "417": "Буквы сливаются в слова, слова складываются в предложения, предложения соединяются в образы, образы сливаются в сюжеты, сюжеты образуют мысль.\nПосле того как мысль становится ясна, она распадается на сюжеты, сюжеты — на образы, образы — на предложения, предложения — на слова, слова — на буквы, буквы плывут перед глазами, веки слипаются, книга выпадает из рук.",
  "418": "1. Уж сколько раз твердили миру, что лесть гнусна, вредна, но только всё не впрок, и в сердце льстец всегда отыщет уголок.\n2. Мы все должны любить своё отечество, потому что здесь мы получили жизнь, впервые увидели свет.\n3. То змейкой, свернувшись клубком, у самого сердца колдует, то целые дни голубком на белом окошке воркует, то в инее ярком блеснёт, почудится в дрёме левкоя, но верно и тайно ведёт от радости и от покоя.\n4. К утру, когда потёмки реже, стог высится, как сеновал, в котором месяц мимоезжий, зарывшись, переночевал.",
  "419": "1. Если бы мы поехали за город, то хорошо бы отдохнули.\n(бы - формообразующая частица, служит для образования условного наклонения)\n2. Пусть всегда будет мир во всем мире!\n(пусть - формообразующая частица, служит для образования повелительного наклонения)\n3. Что за прелесть эти сказки!\n(что за - смыслоразличительная частица, восклицательная)\n4. Давай поедем к морю этим летом.\n(давай - формообразующая частица, служит для образования повелительного наклонения)\nПерестройка предложений:\nХорошо бы мы отдохнули, если бы поехали за город.\nМир во всем мире пусть будет всегда!",
  "420": "1. Как бы вы ответили на поставленные вопросы? (Частица \"бы\" служит для образования условного наклонения. Ответили бы).\n2. Как вы представляете себе большого красивого человека?\n3. Какой художественный приём использован в этом тексте? (Художественный прием - гипербола).\nСписывание текста:\nПо земле идёт большой красивый человек. Перешагивает через реки, перемахивает через горные хребты, а если пускается вплавь, то никакие волны его не остановят.\nБольшой красивый человек знает такие тайны, о которых учёные наших дней только догадываются. Даже солнцу задал он работу: оно вырабатывает электричество.\nВместе с тем именно большой красивый человек многого не знает. Он не знает, что такое ложь и обман. Он не умеет огорчать людей и причинять им боль.\nНе встречал ли ты его где-нибудь? Никого он тебе не напоминает? А может быть, этот большой красивый человек — ты сам, но не сегодняшний, а завтрашний?",
  "421": "1. Всё уснуло в селе. Один только месяц всё так же блистательно и чудно плыл в необъятных просторах роскошного украинского неба, и так же прекрасна была земля в дивном серебряном блеске.\n2. Первый, кто попался им навстречу, это был запорожец, спавший на самой середине дороги, раскинув руки и ноги. Тарас Бульба не мог не остановиться и не полюбоваться на него.\n3. И какой же русский не любит быстрой езды?\n4. Небольшой вал и засека, не хранимые решительно никем, показывали страшную беспечность.\nДополнительный оттенок усиления вносят частицы: только, же.\nДля выражения отрицания служат частицы: не.\n\n--- § 67. Разряды частиц. Формообразующие частицы ---",
  "422": "Функциональная разновидность текста: разговорная речь (диалог).\nФормообразующая частица, о которой идёт речь в тексте - частица \"бы\". Она служит для образования сослагательного (условного) наклонения глагола (сделал бы, придумал бы). Тире в начале строк поставлены, так как это реплики диалога.",
  "423": "1. В дальний путь пускайтеся не вдруг, чтоб ни сулило вам воображенье ваше.\n2. Чтоб музыкантом быть, так надобно уменье и уши ваших понежней, - им отвечает Соловей.\n3. Неужли солнышку лишь только и заботы, чтобы смотреть, как ты растёшь?\nЧастицы в тексте: не, ни, так, лишь, только.",
  "424": "Мама! Мама! С именем этим\nЯ бы хотел подняться в ракете...\nХотел бы (подняться) - условное наклонение.",
  "425": "1. Давай же помянем о нём теперь с тобой вдвоём. (К. Симонов) — Давай-ка мне скорее эту книгу.\nДавай (формообразующая частица) же (смысловая частица) помянем (глагол)... Давай-ка (глагол с частицей) мне (местоимение) скорее (наречие) эту (местоимение) книгу (существительное).\n2. Пускай доводят дело до конца по всем статьям, не пожалев усердья. (К. Симонов) — Пускай змея: ветер усилился.\nПускай (формообразующая частица) доводят (глагол)... Пускай (глагол) змея (существительное)...\n3. Да здравствует солнце! Да скроется тьма! (А. Пушкин) — Светит, да не греет. (Пословица)\nДа (формообразующая частица) здравствует (глагол)... Светит (глагол), да (союз) не (отрицательная частица) греет (глагол).\nОрфограммы: помянем (мять), доводят (II спряжение), до конца (предлог с существительным), статьям (разделительный ь), не пожалев (не с деепричастием, жаль), скроется (что сделает?, I спряжение), светит (II спряжение), не греет (не с глаголом, I спряжение).",
  "426": "Сочинение \"Горе-мечтатель\"\nКомпьютер всё чаще приходит на помощь человеку и даже заменяет его. Некоторым кажется, что компьютеры совсем освободят нас от труда. Именно об этом мечтает мой знакомый Фома. Уж так хочется ему, чтобы умные машины всё делали за него!\nОднажды сидит Фома и мечтает:\n— Давай, робот, делай за меня уроки! Пускай компьютер сам решает задачи по математике, а я буду в игры играть!\nНо робот отвечает ему:\n— Выходит, даже с компьютером без учения не обойтись. Если я за тебя всё решу, то ты ничему не научишься!\nПонял тогда Фома, что труд всегда будет необходим человеку.\n\n--- § 68. Смыслоразличительные частицы ---",
  "427": "1. Ты написал домашнее сочинение? — Разве ты написал домашнее сочинение? / Неужели ты написал домашнее сочинение?\n2. Тебе понравилась тема? — Понравилась ли тебе тема?\n3. Ты делаешь предварительные наброски к сочинению? — Неужели ты делаешь предварительные наброски к сочинению?\n4. У тебя большое сочинение? — Разве у тебя большое сочинение?\n5. Вы научились находить и исправлять лексические и грамматические ошибки? — Научились ли вы находить и исправлять лексические и грамматические ошибки?\n6. А вы сумеете найти в этой работе случаи излишнего повторения одних и тех же слов? — А сумеете ли вы найти в этой работе случаи излишнего повторения одних и тех же слов?\n7. Можно написать хорошее сочинение за один вечер? — Разве можно написать хорошее сочинение за один вечер?",
  "428": "Что за кони у ребят —\nСобственной работы! (Восклицательное предложение).\nЧастица \"Что за\" - восклицательная смыслоразличительная частица.\nГлаголы в условном наклонении: можно было б, сделаться, поскакал бы.\nЧастица \"б\" (\"бы\") служит для образования условного (сослагательного) наклонения.",
  "429": "1. Плутовка к дереву на цыпочках подходит, вертит хвостом, с Вороны глаз не сводит и говорит так сладко, чуть дыша: \"Голубушка, как хороша! Ну что за шейка, что за глазки!\"\nВосхищение: как, что за.\n2. Как осторожно бы вода моя текла и мимо хижинки, и каждого кусточка! Благословляли бы меня лишь берега, и я бы освежал долины и луга, но с них бы не унёс листочка.\n3. Что за диковина! — приятель отвечал.\nУдивление/изумление: что за.\n4. Что за уха! Да как жирна!\nВосхищение: что за, как.",
  "430": "Бежит и бежит дорога. Бежит навстречу солнцу и теплу, которых с каждым километром пути всё больше и больше. Рыхлее, зернистее снег в лесах.\nГлубже лужи. Шумнее ручьи, суше полянки и пригорки. Вот уже кое-где мелькает еле заметная травка. Вон возле ствола осины папоротник вылез, а среди старых пеньков желтеют резиночки мать-и-мачехи.\nУказательные частицы: вот (указывает на что-то ближнее), вон (на что-то более далёкое).\nСредства связи предложений: лексический повтор (бежит), союзы (а), местоимения (которых).\nОрфограммы в последнем предложении: желтеют (жёлтый), резиночки (словарное слово, суффикс -очк-), мать-и-мачехи (правописание сложных слов).",
  "431": "1. В твоём докладе мало живых примеров. Вряд ли понравятся слушателям?\n2. В докладе ты нескромно говоришь о себе и своих успехах. Одобрят ли это ребята?\n3. Доклад у тебя длинноват. Едва ли закончишь ты его за полчаса?\n4. В середине доклада ты затрагиваешь интересный, но не относящийся к теме вопрос. Навряд ли стоит это делать?",
  "432": "1. Читателя надо подготовить к восприятию темы. Поэтому сочинение обычно начинают с введения.\n— Как раз читателя надо подготовить к восприятию темы.\n2. В этом предложении тебе удалось чётко сформулировать вывод. Оно больше всего подходит для концовки сочинения.\n— Именно в этом предложении тебе удалось чётко сформулировать вывод.\n3. Во втором варианте сочинения ты позаботился о том, чтобы между абзацами была ясная связь. Это сделало работу лучше.",
  "433": "1. Гласные звуки состоят исключительно из голоса. (исключительно - выделение, ограничение).\n2. Разделительный ъ пишется только перед буквами е, ё, ю, я после приставок на согласную. (только - выделение, ограничение).\n3. У существительных 3-го склонения после шипящих на конце пишется мягкий знак.\n4. Среди имён существительных есть лишь такие, которые имеют форму множественного числа. (лишь - выделение, ограничение).",
  "434": "1. Ты даже не веришь мне? А ещё другом называешься! (частица даже).\n2. Я очень занят, но помочь тебе всё-таки постараюсь. Мы ведь друзья. (частица ведь).\n3. Ты не посчитался с моим советом. А я же говорил тебе, как лучше поступить. (частица же).\n4. Ты сам хорошо учишься. А товарищ твой запустил ученье. Ему это непростительно. Говорил, говорил о дружбе, а товарищу помочь отказался.\n5. Мне не давались точные науки. А после нескольких занятий с товарищем я почувствовал, что могу их осилить.\n\n--- § 69. Раздельное и дефисное написание частиц ---",
  "438": "1. Я так же, как и ты, люблю читать. (Наречие с частицей - так же).\n2. Он тоже выполнил это задание отлично. (Союз тоже = и).\n3. Мы решили ту же самую задачу. (Местоимение с частицей - ту же).",
  "439": "1. Скажи-ка мне, куда мы идём?\n2. Принеси-ка ту книгу.\n3. Все-таки мы пошли в кино, несмотря на дождь.\n4. Он всё же приехал вовремя.\n5. Мы как-то раз уже были здесь.",
  "440": "Вчера я пошел в библиотеку, чтобы взять нужные книги. Мне нужно было написать доклад по истории. Библиотекарь посоветовала мне ту же самую энциклопедию, которую я брал в прошлом году. Я тоже согласился, что это лучший источник.",
  "441": "1. Что бы мне такого почитать интересного? (Что бы - местоимение с частицей, раздельно).\n2. Чтобы хорошо учиться, надо много стараться. (Чтобы - союз, слитно).\n3. Я то же самое хотел тебе сказать. (То же - местоимение с частицей, раздельно).\n4. Мой брат тоже занимается спортом. (Тоже - союз, слитно).",
  "442": "Распределите слова на две колонки: с дефисным написанием и с раздельным.\nЧерез дефис: скажи-ка, всё-таки, дай-ка, принеси-ка, как-нибудь.\nРаздельно: он же, я ли, пришел бы, такой же, тот же самый.",
  "443": "Составьте предложения со словами \"всё-таки\", \"же\", \"бы\", \"ли\".\n1. Всё-таки мы успели на этот поезд!\n2. Куда же ты запропастился на целый день?\n3. Я хотел бы поехать на море этим летом.\n4. Знаешь ли ты, как решать это уравнение?",
  "444": "Перепишите текст, раскрывая скобки.\nБыло (всё)таки холодно, и мы решили вернуться. Я (то)же замерз, хотя оделся тепло. Что(бы) согреться, мы выпили горячего чая. Мы (так)же обсуждали планы на завтрашний день. Как (же) хорошо дома! (Что)бы ни случилось, дома всегда уютно.\nОтвет:\nБыло всё-таки холодно, и мы решили вернуться. Я тоже замерз, хотя оделся тепло. Чтобы согреться, мы выпили горячего чая. Мы также обсуждали планы на завтрашний день. Как же хорошо дома! Что бы ни случилось, дома всегда уютно.",
  "445": "Сделайте морфологический разбор выделенных частиц.\nЖе - частица, смыслоразличительная, усилительная, неизменяемая часть речи.\nБы - частица, формообразующая (образует условное наклонение), неизменяемая.\nЛи - частица, смыслоразличительная, вопросительная, неизменяемая.\nДаже - частица, смыслоразличительная, усилительная, неизменяемая.\n\n--- § 70. Отрицательные частицы не и ни ---",
  "446": "1. Я не мог не поехать к бабушке. (Двойное отрицание = утверждение).\n2. Он ни разу не ошибся в диктанте. (ни - для усиления отрицания).\n3. Куда ни посмотришь, везде лежат снега. (ни - в придаточном уступительном предложении).",
  "447": "Вставьте подходящие по смыслу отрицательные частицы НЕ или НИ.\n1. Я ... могу ... восхищаться этим пейзажем. (не, не)\n2. В классе ... души. (ни)\n3. Как он ... старался, у него ничего ... вышло. (ни, не)\n4. На небе ... облачка. (ни)\n5. Он ... сказал ... слова. (не, ни)",
  "448": "Перепишите текст, вставляя пропущенные буквы Е или И в частицах.\nОтвет:\n1. Не кто иной, как Пушкин, является солнцем русской поэзии.\n2. Никто иной не смог бы так точно передать чувства.\n3. Во что бы то ни стало я должен закончить работу.\n4. Откуда ни возьмись появилась грозовая туча.\n5. Он не мог не знать об этом правиле.",
  "449": "Составьте пять предложений с двойным отрицанием (не + не).\n1. Я не мог не улыбнуться, глядя на этого забавного котенка.\n2. Мы не можем не согласиться с доводами докладчика.\n3. Он не мог не заметить, как сильно изменился город.\n4. Нельзя не радоваться первым весенним лучам.\n5. Она не могла не прийти на помощь другу в беде.",
  "450": "Не с глаголами пишется раздельно: не знал, не мог, не хотел.\nИсключения - слова, которые без НЕ не употребляются: ненавидел, негодовал.\nПриставка НЕ пишется слитно с существительными и прилагательными, если можно заменить синонимом без НЕ: недруг (враг), неправда (ложь), невысокий (низкий).",
  "451": "Раскройте скобки, объясните правописание НЕ и НИ.\n1. На небе (ни) месяца, (ни) звезд. (ни - усиливает отрицание, повторяющийся союз).\n2. (Не) раз я говорил тебе об этом. (не раз = много раз).\n3. (Ни) разу он не опоздал. (ни разу = никогда).\n4. (Не) один человек пришел на собрание, а целых сто. (не один = много).\n5. (Ни) один не пришел. (ни один = никто).",
  "452": "Напишите небольшой текст (5-6 предложений) на тему \"В зимнем лесу\", используя частицы НЕ и НИ.\nЗимой в лесу не услышишь пения птиц. Кругом не видно ни одной живой души. Как ни всматривайся вдаль, заметишь только белые сугробы да темные стволы деревьев. На снегу нет ни следочка. Но лес вовсе не кажется мертвым, он просто спит. Ничто не нарушает эту величавую тишину.\n\n--- § 71. Различение частицы не и приставки не ---",
  "453": "Не с существительными, прилагательными, наречиями на -о, -е.\nСлитно: неправда, нелепый, неглубокий, немедленно, неряха (без не не употребляется).\nРаздельно: не правда, а ложь (противопоставление); далеко не красивый; ничуть не интересно.",
  "454": "Спишите, раскрывая скобки. Объясните орфограммы.\n1. Он сказал (не)правду. (Слитно - ложь).\n2. Это была (не) правда, а вымысел. (Раздельно - есть противопоставление).\n3. Река (не)глубокая, но широкая. (Слитно - мелкая).\n4. Она выглядела (не)ряшливо. (Слитно - без не не употребляется).\n5. Нам было (ни)сколько (не) скучно. (Раздельно - есть слово с ни).",
  "455": "Различение частицы НЕ и приставки НЕ:\nНе кто иной, как мой брат, принес эту весть. (Раздельно, есть \"как\").\nНикто иной не мог этого сделать. (Слитно).\nНе что иное, как ветер, шумел за окном.\nНичто иное меня не интересовало.",
  "456": "Составьте предложения со словами: неглупый, вовсе не глупый, невежа, не с кем, ни к чему.\n1. Мой новый знакомый оказался неглупым собеседником.\n2. Этот поступок вовсе не глупый, а очень даже расчетливый.\n3. Настоящий невежа никогда не уступит место старшим.\n4. В этом пустом доме мне было совершенно не с кем поговорить.\n5. Твои оправдания теперь ни к чему.",
  "457": "Замените словосочетания одним словом с приставкой НЕ.\n1. Лишенный смелости - несмелый (трус).\n2. Не имеющий образования - необразованный (невежда).\n3. Сопровождаемый неудачей - неудачный.\n4. Относящийся без уважения - неуважительный.\n5. Находящийся в состоянии болезни - нездоровый (больной).",
  "458": "Перепишите текст, исправляя ошибки в употреблении НЕ и НИ.\n(Было) Ни один человек не пришел. Ни раз он ошибался. Ни кто иной не смог помочь.\n(Стало правильно) Ни один человек не пришел. Не раз он ошибался. Никто иной не смог помочь.",
  "459": "Выполните морфологический разбор слов: никто, ничто, никакой.\nНикто - местоимение, отрицательное, начальная форма - никто, И.п., ед.ч., муж.р., в предложении является подлежащим.\nНичто - местоимение, отрицательное, нач. форма - ничто, И.п., ср.р., подлежащее.\nНикакой - местоимение, отрицательное (местоименное прилагательное), нач. форма - никакой, И.п., ед.ч., муж.р., определение.",
  "460": "Подготовка к диктанту по темам \"Частица НЕ и приставка НЕ\", \"Частицы НЕ и НИ\".\n(Текст для самопроверки переписан без ошибок: Ни разу не оступился; не мог не заметить; ниоткуда не ждали; ни к кому не обращался; не кто иной, как директор; никто иной не смел; неглубокая речонка; вовсе не глубокий пруд).\n\n--- § 72. Междометие как часть речи ---",
  "461": "1. Ах, как красиво в лесу осенью! (Ах - междометие, выражает восторг).\n2. Ой, я, кажется, забыл ключи. (Ой - междометие, выражает испуг/сожаление).\n3. Ура! Мы победили в соревнованиях! (Ура - междометие, выражает радость).",
  "462": "Найдите междометия в предложениях, определите их значение и расставьте знаки препинания.\n1. Ого, какую большую рыбу ты поймал! (удивление)\n2. Тьфу, какая гадость! (отвращение)\n3. Увы, лето закончилось слишком быстро. (сожаление)\n4. Эй, подождите меня! (оклик, призыв к вниманию)\n5. Ба, да это же мой старый школьный товарищ! (удивление)",
  "463": "Отличие междометий от самостоятельных и служебных частей речи.\nМеждометия не называют предметы, признаки или действия, не являются членами предложения, не изменяются. Они только выражают чувства и побуждения, но не называют их. Этим они отличаются от самостоятельных частей речи. В отличие от служебных, они не служат для связи слов в предложении.",
  "464": "Составьте диалог, используя различные междометия.\n— Привет! Давно не виделись!\n— Ба, кого я вижу! Сколько лет, сколько зим!\n— Ой, ты так изменился, возмужал.\n— Ага. А ты всё такой же веселый. Слушай, пойдем сегодня в парк?\n— Увы, сегодня я не могу, много уроков.\n— Эх, жаль. Ну ладно, тогда до завтра!\n— Угу, пока!",
  "465": "Спишите, расставляя знаки препинания при междометиях.\n1. Чу, где-то раздался выстрел!\n2. Эй, кто там идет?\n3. Увы, наши надежды не оправдались.\n4. Ба, знакомые все лица!",
  "466": "Выделите междометия. Разделите их на группы: выражающие чувства и выражающие побуждение.\nЧувства: ах, ох, увы, боже мой, батюшки, ура, фу, тьфу, ого.\nПобуждение (оклик, призыв): эй, ау, алло, цыц, брысь, караул, марш.",
  "467": "Составьте предложения со словами: марш, брысь, ау, алло.\n1. Марш отсюда, пока я не рассердился!\n2. Брысь со стола, хитрый кот!\n3. Ау, есть кто-нибудь в этом густом лесу?\n4. Алло, это квартира Ивановых?\n\n--- § 73. Дефис в междометиях ---",
  "468": "Междометия, образованные повторением основ, пишутся через дефис:\nОй-ой-ой, ха-ха-ха, хи-хи-хи, бай-бай, динь-динь.",
  "469": "Спишите, раскрывая скобки.\n1. Ха-ха-ха! — громко рассмеялся зритель.\n2. Ой-ой-ой, как болит зуб!\n3. Ку-ку, ку-ку! — раздавалось из чащи.\n4. Баю-бай, усни, мой малыш.",
  "470": "Составьте предложения со сложными междометиями.\n1. \"Хе-хе-хе,\" - хитро усмехнулся дед.\n2. Ого-го, какой высокий небоскреб построили!\n3. Ай-ай-ай, как не стыдно обманывать товарищей!\n4. Ну-ну, не стоит так сильно расстраиваться из-за пустяков.",
  "471": "Перепишите текст, расставляя дефисы.\nТихо в лесу. Только где-то вдалеке слышится: \"Тук-тук-тук\". Это дятел долбит кору. Вдруг из кустов выскочил заяц: \"Прыг-скок!\". А высоко в небе летит журавлиная стая: \"Курлы-курлы\".\nОтвет:\nТихо в лесу. Только где-то вдалеке слышится: \"Тук-тук-тук\". Это дятел долбит кору. Вдруг из кустов выскочил заяц: \"Прыг-скок!\". А высоко в небе летит журавлиная стая: \"Курлы-курлы\".",
  "472": "Вставьте пропущенные междометия, подходящие по смыслу. Пишите их через дефис.\n1. ________, как холодно сегодня на улице! (Ой-ой-ой)\n2. ________, малыш, закрывай глазки. (Баю-бай)\n3. Мальчишки весело смеялись: ________! (Ха-ха-ха)\n4. ________, кто там стучит в дверь? (Тук-тук)",
  "473": "Морфологический разбор.\nОй-ой-ой — междометие.\n1. Выражает чувство (сильную боль/испуг/сожаление).\n2. Неизменяемое слово.\n3. Синтаксическая роль — не является членом предложения.\n\n--- § 74. Звукоподражательные слова ---",
  "474": "Звукоподражательные слова:\n1. Мяу-мяу, - жалобно запищал котенок.\n2. Ку-ка-ре-ку! - раздалось на рассвете.\n3. Гав-гав! - грозно залаял пес на прохожего.\nВ отличие от междометий, звукоподражательные слова не выражают эмоций, а только имитируют звуки природы и животных.",
  "475": "Выпишите из текста звукоподражательные слова.\nРано утром в деревне шумно. \"Му-у!\" - мычит корова, просясь на луг. \"Бе-е!\" - откликаются овцы. Возле пруда слышится громкое \"кря-кря\". А на крыше дома воркуют голуби: \"Гурр-гурр\".\nОтвет: Му-у, Бе-е, кря-кря, Гурр-гурр.",
  "476": "Образуйте от звукоподражательных слов глаголы.\nМяу — мяукать.\nГав — гавкать (лаять).\nКукареку — кукарекать.\nКря — крякать.\nЧик-чирик — чирикать.\nХрю — хрюкать.\nЖу-жу — жужжать.",
  "477": "Спишите предложения, вставляя подходящие по смыслу звукоподражательные слова.\n1. Часы на стене мерно отсчитывали время: ... (тик-так, тик-так).\n2. Воробей прыгал по ветке и весело пел: ... (чик-чирик).\n3. Поезд приближался к станции: ... (чух-чух-чух).\n4. Лягушки на болоте затянули свою песню: ... (ква-ква).",
  "478": "Разделите слова на две группы: 1) Междометия, 2) Звукоподражательные слова.\nСлова: ах, бац, динь-динь, увы, гав-гав, караул, хрю-хрю, браво, ку-ку, шлеп.\n1) Междометия: ах, увы, караул, браво, бац, шлеп. (Примечание: бац и шлеп иногда относят к звукоподражательным, но они часто выступают в роли междометий).\n2) Звукоподражательные слова: динь-динь, гав-гав, хрю-хрю, ку-ку.",
  "479": "Придумайте небольшой рассказ для детей, в котором животные \"разговаривают\", используя звукоподражательные слова.\nНаступило утро на ферме. Первым проснулся петух Петя и громко закричал: \"Ку-ка-ре-ку!\". От его крика проснулся пес Шарик: \"Гав-гав! Кто здесь шумит?\". Тут из сарая вышла корова Зорька: \"Му-у! Пора на пастбище\". Маленькие поросята тоже проснулись и весело захрюкали: \"Хрю-хрю-хрю, дайте нам поесть!\". А пушистый котенок Мурзик только лениво потянулся на крыльце и промурлыкал: \"Мур-мяу, как хорошо спать на солнышке\". Так начался новый день.",
  "480": "Напишите сочинение с использованием частиц и междометий.\nОх, и трудная была задачка! Как бы я ни старался, ответ никак не сходился. Неужели я допустил ошибку в самом начале? \"Эх, надо было внимательнее читать условие!\" - подумал я. Давай-ка перепроверю все вычисления. И точно, именно в третьем действии я забыл перенести запятую. Ура! Теперь всё сошлось! Вряд ли кто-то решит её быстрее меня. Какой же я молодец, что не сдался!",
  "490": "Разговорная речь: разговор приятелей, письмо к другу.\nНаучный стиль: монография.\nОфициально-деловой стиль: расписка, объявление, указ.\nПублицистический стиль: статья в газету, репортаж.\nЯзык художественной литературы: повесть, басня.",
  "491": "Текст является художественным, так как он написан в стихотворной форме, обладает образностью, передаёт чувства и настроение автора с помощью эпитетов и метафор (разорванной тучи, трубы весны затрубят).\nЗаголовок: Оттепель (или Приближение весны).\nОттепель после метели.\nТолько утихла пурга,\nРазом сугробы осели\nИ потемнели снега.\nВ клочьях разорванной тучи\nБлещет осколок луны.\nСосен тяжёлые сучья\nМокрого снега полны...\nСкоро проснутся деревья,\nСкоро, построившись в ряд,\nПтиц перелётных кочевья\nВ трубы весны затрубят.\n(Н. Заболоцкий)\nОрфограммы: потЕмнели (тёмный), клочЬях (разделительный ь), разорваННой (причастие с приставкой), блещЕт (I спряжение), тяжЁлые (тяжесть), сучЬя (разд. ь), проснуТся (что сделают?), кочевЬя (разд. ь).",
  "492": "1. Текст — официальное благодарственное письмо. Автор: Н. Латынина, художественный руководитель ансамбля. Адресат: администрация города. Части: обращение, выражение благодарности (основная часть), надежда на продолжение контактов, подпись, дата.\n2. Текст — официальное письмо-запрос/просьба. Автор: М.А. Иванов, ученик. Адресат: председатель оргкомитета научного форума. Части: обращение, сообщение о невозможности присутствовать, просьба выслать сборник, благодарность, подпись, дата.\nЗадачи авторов: в первом случае — выразить благодарность; во втором — попросить о пересылке сборника статей.",
  "493": "Уважаемая Мария Ивановна!\nОт всей души поздравляю Вас с замечательным весенним праздником — 8 Марта! Желаю Вам крепкого здоровья, весеннего настроения, радости и улыбок. Пусть каждый день приносит только хорошие новости, а ученики радуют своими успехами!\nС уважением, Ваш ученик.",
  "494": "Пример письма официально-делового стиля:\nДиректору ООО \"Вектор\"\nИванову И. И.\nот менеджера Петрова П. П.\nЗаявление\nПрошу предоставить мне ежегодный оплачиваемый отпуск с 15 мая по 28 мая 2023 года.\nДата, подпись.\nОсобенности: строгая форма, отсутствие эмоций, наличие стандартных реквизитов (шапка, название документа, дата, подпись).",
  "495": "Заголовок: История русских колоколов.\nДиалог с элементами разговорной речи:\n— Ребята, а вы знаете, для чего на Руси использовали колокола? — спросил экскурсовод.\n— Наверное, чтобы звать людей в церковь? — ответил кто-то из группы.\n— Не только! С самого зарождения русские колокола были призваны не только приглашать на богослужение, но и становились участниками радостей и бед народа.\n— А они все одинаковые были?\n— Нет, в зависимости от назначения колокола отличались. Например, набатные колокола предупреждали о врагах или пожарах. Их звон был особенным, чтобы горожане сразу узнавали сигнал.\n— А где висели такие колокола?\n— Раньше они висели на Спасской и других башнях Московского Кремля. А вот в Великом Новгороде были вечевые колокола — они созывали свободных горожан на площадь для решения важных дел.\nПолучился диалог-расспрос.",
  "496": "(Устные и творческие задания — доклады и этикетные диалоги, выполняются индивидуально устно).",
  "497": "(Устные и творческие задания — доклады и этикетные диалоги, выполняются индивидуально устно).",
  "498": "(Устные и творческие задания — доклады и этикетные диалоги, выполняются индивидуально устно).",
  "499": "Смысл высказывания Л. Толстого в том, что нужно развивать собственную память и мышление, а не полагаться только на внешние источники (книги, записи). В классе по этому поводу обычно звучит диалог-обмен мнениями (дискуссия).",
  "500": "Совпадают (буква = звук): бетон, график, комендант, вариант.\nНе совпадают: акварель (в - [в'], е - [э]), автор (в - [ф]), гостиница (г - [г], т - [т'], и - [и], н - [н'], и - [и], ц - [ц], а - [а]), каморка, чемпион (е - [и]), реагировать, гараж (ж - [ш]), отражение, калитка (т - [т]), квартира, миллиард (д - [т]), автор (в - [ф]).\nПримеры: б - [п] (дуб), з - [с] (глаз), г - [к] (снег), т - [ц] (братца).",
  "501": "1. Ещё не царствует река,\nНо синий лёд она уж топит;\nЕщё не тают облака,\nНо снежный кубок солнцем допит.\n2. И в самом обычном наряде\nМила ты, Отчизна, до слёз.\nК лицу тебе русые пряди\nТвоих ненаглядных берёз.\nПодчёркнутые буквы, не совпадающие со звуками: (с)о(л)нцем - л не произносится, наряд(е) - е слышится как [и], сл(ё)з - з слышится как [с], бер(ё)з - з слышится как [с].",
  "502": "Слова для таблицы:\nГласные ударные: [о] (в слове дом), [а] (сад)\nГласные безударные: [а] (в слове вода - в[а]да)\nСогласные звонкие мягкие: [б'] (белый)\nСогласные глухие твердые: [к] (кот)",
  "503": "Не все буквы обозначают звуки (ъ и ь звуков не обозначают). Буквы можно разделить на гласные и согласные.\nПисать четким почерком важно для того, чтобы написанное могло быть правильно прочитано и понято другими людьми, особенно в официальных документах, письмах.",
  "504": "(Текст на стр. 105).\nСвежая струя пробежала по моему лицу. Я открыл глаза: утро начиналось. Ещё нигде не румянилась заря, но уже забелелось на востоке... Всё стало видно, хотя смутно видно, кругом. Бледно-серое небо светлело, холодело, синело; звёзды то мигали слабым светом, то исчезали; отсырела земля, запотели листья, кое-где стали раздаваться живые звуки, голоса, и жидкий, ранний ветерок уже пошел бродить и порхать над землёю.\nВиды орфограмм: приставки на з/с (исчезали, раздаваться), чередующиеся гласные в корне (заря), безударные гласные (пробежала, светлело), дефисное написание сложных прилагательных (бледно-серое) и наречий (кое-где, по-моему).",
  "505": "Обыгрывается языковое явление — паронимы (праздничность — праздность, вспомнил — помнил, прожитым — пережитым).\nЦель — подчеркнуть смысловую разницу, усилить выразительность речи.\nСтилистическая принадлежность: художественный стиль.",
  "506": "Шла весна. Сильнее пригревало солнце. На южных склонах бугров потаял снег, и рыжая от прошлогодней травы земля в полдень уже покрывалась прозрачной сиреневой дымкой испарений. На сугревах, на куртинах, из-под вросших в суглинок самородных камней показались первые, ярко-зелёные острые ростки травы медунки. Обнажилась зябь. С брошенных зимних дорог грачи перекочевали на гумна, на затопленную талой водой озимь. В логах и балках снег лежал синий, доверху напитанный влагой; оттуда всё ещё сурово несло холодом, но уже тонко и певуче звенели в ярах под снегом невидимые глазу вешние ручейки, и совсем по-весеннему, чуть приметно и нежно зазеленели в перелесках стволы тополей.\nСтиль: художественный. Нераспространенные предложения: Шла весна. Обнажилась зябь.\nДиалектные слова: сугревы, куртины, гумна, яр.",
  "507": "Приставочный: подзаголовок, безопасный, вбежать.\nСуффиксальный: подберёзовик, слушатель, рыбацкий, обдуманно.\nПриставочно-суффиксальный: безрезультатный.\nСложение: сенокосилка, вуз, кресло-кровать.\nПереход из одной части речи в другую: весной, дежурный.",
  "508": "Физкультура (сложение), подшефный (приставочно-суффиксальный), безъядерный (приставочно-суффиксальный), ракета-носитель (сложение), гимназист (суффиксальный), прилуниться (приставочно-суффиксальный), велогонки (сложение), КВН (аббревиация), печник (суффиксальный), неприсоединение (приставочный), приземлиться (приставочно-суффиксальный), запрограммировать (приставочный), самолёт (сложение).",
  "509": "1. В каждых сутках есть такой\nСмутный и тревожный час.\nГромко говорю с тоской,\nНе раскрывши сонных глаз. (сон + н)\nИ она стучит, как кровь,\nКак дыхание тепла,\nКак счастливая любовь,\nРассудительна и зла. (рас + суд)\n2. ...В среднерусской полосе (рус + ск)\nВасильковые рассветы (рас + свет)\nПроплывают по шоссе.\nЗнать состав слова нужно было в словах: сонных, рассудительна, среднерусской, рассветы, так как удвоенная согласная образуется на стыке морфем.",
  "510": "Рыбачить (рыб-ач-и-ть), тепловозный (тепл-о-воз-н-ый), асфальтировать (асфальт-ир-ова-ть), расщелина (рас-щел-ин-а), разгореться (раз-гор-е-ть-ся), иссушить (ис-суш-и-ть), морозостойкий (мороз-о-стой-к-ий), легендарный (легенд-арн-ый), насмешница (на-смеш-ниц-а), собеседник (со-бесед-ник), бескрайний (бес-край-н-ий), арендатор (аренд-атор), вмятина (в-мят-ин-а), тёмненький (тёмн-еньк-ий), несчастье (не-счасть-е), легкоатлетический (легк-о-атлет-ическ-ий), первооткрыватель (перв-о-откры-ва-тель), безвкусица (без-вкус-иц-а), восторженный (восторж-енн-ый), распрекрасный (рас-пре-красн-ый), подкормка (под-корм-к-а), принарядиться (при-наряд-и-ть-ся), сверхскорость (сверх-скорость), выигрыш (вы-игр-ыш), предыстория (пред-ыстори-я), привокзальный (при-вокзаль-н-ый), посланец (по-слан-ец), бесчеловечный (бес-человеч-н-ый), бессмыслица (бес-смысл-иц-а), рыбхоз (рыб-хоз), разгрести (раз-грес-ти), комплексный (комплекс-н-ый), пилотировать (пилот-ир-ова-ть), быстрозамороженный (быстр-о-за-морож-енн-ый), вскарабкаться (вс-карабк-а-ть-ся), лицеист (лице-ист), приземлиться (при-земл-и-ть-ся).",
  "511": "Языковые средства, отражающие публицистический стиль: общественно-политическая и высокая лексика (Родина, долг, великий, святым), призывность (пусть... сопутствуют).\nДЕНЬ ПОБЕДЫ\nДля нашей Родины всегда будет святым день 9 Мая, и всегда люди мысленно будут возвращаться к маю 1945 года. В те весенние дни был закончен великий путь, отмеченный многими жертвами. И наш человеческий долг: поздравляя друг друга с праздником, всегда помнить о тех, кого нет с нами, кто пал на войне.\nПразднуя Победу, мы всегда будем вспоминать, какие качества нашего народа помогли одолеть врага. Терпенье. Мужество. Величайшая стойкость. Любовь к Отечеству. Пусть эти проверенные огнём войны качества всегда нам сопутствуют. И всегда победа будет за нами.",
  "512": "Самостоятельные части речи:\n- изменяемые: склоняемые (имя существительное, имя прилагательное, имя числительное, местоимение, причастие); спрягаемые (глагол).\n- неизменяемые (наречие, деепричастие, категория состояния).\nСлужебные части речи: предлог, союз, частица.\nМеждометие: междометие.\nСмысловое значение: существительное обозначает предмет, прилагательное — признак предмета, глагол — действие.",
  "513": "1. Ночи были теплы и непроглядны, в чёрной тьме плыли, мерцали, светили топазовым светом огненные мухи, стеклянными колокольчиками звенели древесные лягушки.\n2. В прибрежном овраге, спускавшемся из лесу к морю, быстро прыгала по каменистому ложу мелкая, прозрачная речка.\n3. Как чудесно дробился, кипел её блеск в тот таинственный час, когда из-за гор и лесов, точно какое-то дивное существо, пристально смотрела поздняя луна!\n4. Горячее солнце было уже сильно, чисто и радостно.\n5. В лесах лазурно светился, расходился и таял душистый туман, за дальними лесистыми вершинами сияла предвечерняя белизна снежных гор.\nХарактерные для художественного текста слова (эпитеты и метафоры): непроглядны, огненные, стеклянными, таинственный, дивное.",
  "514": "Это мой (местоим.) портфель — мой (глагол в повел. накл.) руки. Простой (прил.) план — простой (сущ.) вагонов на станции. Бег (сущ.) на месте — бегать (глагол) по площадке. Зелёные (прил.) листья берёзы — зеленеющие (причастие) листья берёзы. Белизна (сущ.) облаков — белеющие (причастие) облака — белые (прил.) облака — белеть (глагол) на фоне неба. Тройка (сущ.) за ответ — три (числит.) товарища — тройной (прил.) прыжок — утраивать (глагол) силы. Положить выше (нареч.) — этот дом выше (прил. в сравнит. степ.). Решение неверно (кр. прил.) — отвечал неверно (наречие).\nПостоянные признаки изменяемых частей речи:\nУ существительного: собственное/нарицательное, одушевленное/неодушевленное, род, склонение.\nУ прилагательного: разряд (качественное, относительное, притяжательное).\nУ глагола: вид, спряжение, переходность, возвратность.",
  "515": "Заголовок: Александр Невский.\nИмена собственные: Александр Невский, Новгороде, Руси, Неве, Невский, Изборск, Псков, Новгороду, Чудского озера, Ледового побоища.\nЧасти речи во втором абзаце:\nВначале (нареч.) он (местоим.) княжил (глаг.) в (предл.) Новгороде (сущ.). Когда (союз) на (предл.) эту (местоим.) территорию (сущ.) вторглись (глаг.) шведы (сущ.), князь (сущ.) Александр (сущ.) успешно (нареч.) отразил (глаг.) их (местоим.) атаки (сущ.). И т.д.\nСлужебные части речи: в, на, к (предлоги — выражают зависимость слов), и, когда (союзы — связывают части предложений).",
  "516": "1. Свернув с просеки, мы направились (глаг.) по утоптанной тропинке...\n2. На пригорке, как баррикады, навалены (кр. причастие) сломанные и вывороченные с корнями деревья.\n3. Всклокоченные тучи, клубясь, быстро несутся (глаг.) невесть куда.\n4. Ветер, угомонившись за ночь, замер (глаг.).\n5. Небо украшено (кр. причастие) узорами сверкающих звёзд.\n6. Весь город залит (кр. причастие) мерцающими огнями, над ним, раздвинув тьму, висит (глаг.) матовый свет.\n7. Комната узкая (прил.), длинная (прил.); все полки уставлены (кр. причастие) книгами.\nГлагол: несутся — несов. вид, I спр., возвратный, непереходный; в форме изъявит. накл., наст. вр., мн.ч., 3 лица. В предложении — сказуемое.",
  "517": "Тема текстов: память о погибших героях. Описание представляет собой второй фрагмент (описание обелиска).\n1. Десант был выброшен ночью. Семеро моряков попрыгали в мелкую воду и, едва удерживаясь на ногах, стали пробираться к берегу. Они шли, спотыкаясь о камни, поддерживая друг друга. Наконец море выпустило их на берег.\n(Деепричастия: удерживаясь, спотыкаясь, поддерживая — обстоятельства. Причастий нет).\n2. На окраине городка, на берегу моря, стоит серый обелиск. Он похож на большой кинжальный штык, поблёскивающий (причастие, определение) на солнце. У подножия обелиска лежат цветы. Веточка гвоздики с горящим (причастие, определение) пунцовым цветком похожа на маленький факел. В застывшем (причастие, определение) бетоне белела табличка. На ней было написано: Вечная слава участникам героического десанта. Дальше шли имена погибших.",
  "518": "Текст о словах разных частей речи.\nЕсли вы заглянете (I спр.), скажем, в «Словарь русского языка» С. И. Ожегова, то найдёте в нём два слова вон: указательная частица («Вон он идёт») и наречие («выйти вон»). О междометии ничего не говорится. А ведь в контекстах типа «Вон отсюда!» слово «вон» имеет значение «прочь, уходи» и уже не является ни указательной частицей, ни наречием. Значит, в русском языке сейчас три слова вон, а одно из них — последнее — представляет собой междометие, синонимичное слову прочь.\nОбъяснение: заглянете (I спр., безударное окончание), ничего (в отрицат. местоимении без ударения - ни), не говорится (не с глаголом раздельно), не является (не с глаголом), ни указательной, ни наречием (повторяющийся союз ни... ни при перечислении).",
  "519": "(Примерный анализ видов орфограмм на основе изученного в 5-7 классах)\nПравописание гласных: а) в приставках (пре/при-, роз/раз-); б) в корнях (безударные проверяемые, непроверяемые, чередующиеся -гар/-гор, -зар/-зор, -раст/-рос и др.); в) в суффиксах (ова/ева, ива/ыва у глаголов; ек/ик у существительных); г) в окончаниях (Е/И в безударных окончаниях существительных и глаголов).",
  "520": "(Примерный анализ видов орфограмм на основе изученного в 5-7 классах)\nПравописание согласных: а) в приставках (на з/с: раз/рас, без/бес); б) в корнях (непроизносимые согласные, глухие/звонкие); в) в суффиксах (н/нн в прилагательных и причастиях, чик/щик).",
  "521": "(Примерный анализ видов орфограмм на основе изученного в 5-7 классах)\nУпотребление дефиса: а) между приставкой и корнем (по-русски, кое-кто); б) между корнями (русско-английский); в) между корнем и суффиксом (кто-то, где-нибудь); г) между словами (из-за, из-под).",
  "522": "(Примерный анализ видов орфограмм на основе изученного в 5-7 классах)\nСлитно/раздельно: а) самостоятельных слов (не с существительными, прилагательными, причастиями); б) приставок в наречиях (вдаль, наверх); в) служебных слов (также, тоже, чтобы, в течение, в продолжение).",
  "523": "Орфографический разбор:\nИспуг — приставка ис- (перед глухим п), корень -пуг (на конце парный согласный, проверочное слово — испугать).\nМетро — словарное слово, несклоняемое существительное, непроверяемая гласная \"е\" в корне.\nКазацкий — суффикс -к- пишется после основы на ц.\nСупчик — суффикс -чик- пишется после основы на п.\nСклеенный — приставка с- (неизменяемая), суффикс -енн- в страдательном причастии прошедшего времени от глагола на -ить (склеить).\nНавсегда — наречие, пишется слитно, приставка на-, корень -всегда.",
  "524": "Растаял (гласная перед л в прош.вр. - как в инфинитиве растаять), луга зазеленели (зелень - зелёный), Телеги вновь грохочут (грохот) по мосту, И воробьи (разделительный ь) от солнца (солнышко) опьянели (разделительный ь, пьяный), И яблони качаются (качка, что делают?) в цвету. Раскрыты (приставка рас- перед глухим к) окна. Веет (I спр.) тёплый ветер (словарн.), И лёгкий (лёгок) пар клубится (что делает?) у реки. И шумно солнцу радуются (что делают?) дети, И думают (I спр.) о жизни (жи-ши) старики (старый).",
  "525": "В мире слов разнообразных,\nЧто блестят, горят и жгут, —\nЗолотых, стальных, алмазных, —\nНет священней слова: «труд»!\nИ на место в жизни право\nТолько тем, чьи дни — в трудах:\nТолько труженикам — слава,\nТолько им — венок в веках!\nИ, окончив день, усталый,\nКаждый щедро награждён,\nЕсли труд, хоть скромный, малый,\nБыл с успехом завершён!\nВиды орфограмм: безударные гласные в корне, чередующиеся гласные в корне, разделительный ь, падежные окончания существительных, н/нн в суффиксах, о/ё после шипящих.",
  "526": "Я зарастаю памятью,\nКак лесом зарастает пустошь.\nИ птицы-память по утрам поют,\nИ ветер-память по ночам гудит,\nДеревья-память целый день лепечут.\nИ там, в пернатой памяти моей,\nВсе сказки начинаются с «однажды».\nИ в этом однократность бытия\nИ однократность утоленья жажды.\nНо в памяти такая скрыта мощь,\nЧто возвращает образы и множит...\nШумит, не умолкая, память-дождь,\nИ память-снег летит и пасть не может.",
  "527": "Словосочетания с предлогами: влажной от дождя, лежавшие на земле, окрашенные в цвет, сквозили перед глазами. (Связь выражена с помощью предлогов от, на, в, перед).",
  "528": "Дверь (подлежащее) поддалась (сказуемое) не сразу, затем сладко хрустнула (сказуемое), и в лицо ударил (сказуемое) блистательный мороз (подлежащее). Песком, будто рыжей корицей, усыпан (сказуемое) был ледок (подлежащее), облепивший ступени крыльца, а с выступа крыши, остриями вниз, свисали (сказуемое) толстые сосули (подлежащее), сквозящие зеленоватой синевой. Сугробы (подлежащее) подступали (сказуемое) к самым окнам флигеля, плотно держали (сказуемое) в морозных тисках оглушённое деревянное строеньице (дополнение). Перед крыльцом чуть вздувались (сказуемое) над гладким снегом белые купола (подлежащее) клумб, а дальше сиял (сказуемое) высокий парк (подлежащее).",
  "529": "1. Весна (сущ.) наступила (глаг.).\n2. Два (числит.) — это число (сущ.).\n3. Ты (местоим.) написал (глаг.) сочинение?\n4. Осень (сущ.) пришла (глаг.).\n5. Поле (сущ.) огорожено (кр. прич.).\n6. Лес (сущ.) — хранитель (сущ.) вод.\n7. Небо (сущ.) синее (прил.).\n8. Ветер (сущ.) колюч (кр. прил.).\nСпособы выражения главных членов: существительное, местоимение, числительное (подлежащее); глагол, существительное, прилагательное, краткое причастие, краткое прилагательное (сказуемое).",
  "530": "1. Вопросительное. 2. Побудительное (✔). 3. Повествовательное. 4. Вопросительное. 5. Повествовательное. 6. Повествовательное.\n2. Ты цвети красой, степь привольная! ✔",
  "531": "Заголовок: Студёный май. (или Кораблик).\nОднородные члены: вырезал и прикрепил (сказуемые); по бликам, по реке (обстоятельства).\nОсновы: зябли почки, земля цвела, я вырезал и прикрепил; он уплывал; я не прощался, не махал, но было грустно; вода смешалась, парус качался и таял.",
  "532": "Заголовок: Великий композитор.\nа) На самых престижных сценах России и зарубежья звучат его произведения — «Евгений Онегин», «Пиковая дама», «Лебединое озеро», «Спящая красавица», «Щелкунчик», Четвёртая, Пятая и Шестая симфонии и др.\nб) В 22 года П. И. Чайковский поступил в Петербургскую консерваторию, в которой проявил себя как один из самых талантливых учеников. Обладая необыкновенным музыкальным даром, композитор пополнил сокровищницу мирового искусства своими прекрасными произведениями.\nв) Призвание у будущего композитора обнаружилось рано, уже в четыре года он написал музыкальную пьесу.",
  "533": "(Устное задание для работы в группах - доклад о музыкальном произведении, публицистический стиль).",
  "534": "...Пусть жизнь ликует на земле,\nПока земля живая.\nЗемля — твой мир, твой отчий дом,\nТвои любовь и дети.\nХрани её своим трудом\nИ песней на рассвете.\nПунктуационные правила: запятая между простыми предложениями в составе сложного, тире между подлежащим и сказуемым, выраженными существительными в именительном падеже (Земля - дом).",
  "535": "1. Мелколесье. Степь и дали. Свет луны во все концы... вот опять вдруг зарыдали разливные бубенцы.\n2. Неприглядная дорога да любимая навек, по которой ездил много всякий русский человек.\n3. Эх вы, сани! Что за сани!\n4. Тот, кто видел хоть однажды этот край и эту гладь, тот почти берёзке каждой ножку рад поцеловать. (От главного к придаточному: Тот (кто именно?), кто видел...).\n5. Полюбил я седых журавлей с их курлыканьем в тощие дали, потому что в просторах полей они сытных хлебов не видали. (От главного к придаточному: Полюбил (почему?), потому что...).",
  "536": "Разбивка на абзацы (по смыслу: первый — описание вишняка, второй — описание действий/звуков и затишья).\nЗа усыпанной красным песком площадкой, с маленькими следками ног, за длинными клумбами закрывшегося на день табака и белых левкоев дремал в полном солнце вишняк, вспугиваемый вороватым вспархиванием воробьиной силы.\nКто-то невидимый встряхивал вдруг неприметную в солнечной синеве бечеву, и уснувшие в воздухе сухие дощечки начинали сыпать тревожным щёлканьем. Покачивались и замирали, как усталые крылья. На площадке играли Лиля и Мара, но играли неслышно, и в наступившем затишье стоял только неопределённый шорох.\n(Деление совпадает со смысловыми частями: статичное описание спящей природы переходит к описанию внезапного действия и звуков).",
  "537": "Ошибочные рассуждения Перекладина заключаются в том, что он считал постановку знаков препинания случайной или механической («чем путанее бумага... тем больше запятых», «каждого чиновника надо запятой отделять», «чтоб секретарь слюной не истёк»). На самом деле знаки препинания ставятся по строгим пунктуационным правилам, зависят от синтаксического строения предложения, наличия однородных членов, вводных слов, обособлений, сложных конструкций и служат для правильной передачи смысла высказывания.",
  "538": "Далеко где-то рокотал гром, (4) и его ворчливые звуки всё приближались. Крупные капли дождя стали падать и ударяться о траву. Трава металлически шелестела. Вот грянул гром, (4) и тучи, (6) охваченные синим огнём, (6) дрогнули. Крупный дождь полился ручьями, (4) и удары грома, (6) непрерывно рокотавшие, (6) казались в этой пустынной степи угрожающими. Трава, (6) сгибаемая ударами ветра и дождя, (6) ложилась на землю. Молнии, (6) слепившие глаза, (6) рвали тучи. В голубом блеске их вдали вставала горная цепь, (6) сверкавшая синими огнями. Когда молнии гасли, (4) она исчезала, (2) как бы проваливалась в темную пропасть. Всё гремело, (2) вздрагивало, (2) отталкивало звуки и родило их. Земля, казалось, вздрагивала перед гневом небес. А мне было весело.\nДивный хаос увлекал меня, (2) настраивал на героический лад. И чем мне было выразить моё великое волнение и мой восторг перед грандиозной картиной природы? Я запел громко, во всю силу. Ревел гром, (4) блистали молнии, (4) а я пел и чувствовал себя в полном родстве со всеми звуками.",
  "539": "Язык, великолепный наш язык, (Обособленное приложение)\nРечное и степное в нём раздолье...\nВ нём воркованье голубя весной,\nВзлёт жаворонка к солнцу — выше, выше. (Тире перед уточнением, запятая между повторяющимися словами)\nБерёзовая роща. Свет сквозной.\nНебесный дождь, просыпанный по крыше... (Обособленное определение, выраженное причастным оборотом)\n(К. Бальмонт)"
};
  const tasks = course.flatMap(chapter => chapter.tasks || []);

  for (const task of tasks) {
    const answer = solutions[String(task.key)];
    if (!answer) continue;

    task.answer = answer;
    task.rule = 'Решение выполнено по условию упражнения с соблюдением орфографических, пунктуационных и речевых норм.';
    task.steps = [
      'Прочитали условие и определили, какие действия нужно выполнить.',
      'Применили правила русского языка и проверили написание и знаки препинания.',
      'Записали готовый ответ в порядке, указанном в упражнении.'
    ];
    task.summaryOnly = false;
    task.answerPending = false;
  }
})();
